#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BOperationRiskTests {
  internal static JObject Packet()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-operation-risk-traces-20261003.json"))["traces"].Single(t=>(string)t["name"]=="bound-original-read")["response"].DeepClone();
  static object Invoke(object owner,string method,params object[] args){var t=owner as Type??owner.GetType();var m=t.GetMethod(method);Assert.NotNull(m,"Missing risk boundary: "+method);try{return m.Invoke(owner is Type?null:owner,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  internal static object Read(JObject p=null,JObject binding=null,string hash=null){p=p??Packet();var type=typeof(CombatExactValue).Assembly.GetType("LastRail.Battle.BOperationRiskSource");Assert.NotNull(type,"Missing immutable original risk mapper");return Invoke(type,"Read",p,binding??(JObject)p["binding"].DeepClone(),hash??(string)p["packetHash"]);}
  internal static JObject Pipeline(JObject raw=null,int defense=1000)=>new JObject{["version"]=CombatNumericDefenseBudget.Version,["base"]=raw??new JObject{["numerator"]="60",["denominator"]="1"},["defense"]=new JObject{["numerator"]=defense.ToString(),["denominator"]="1"},["effects"]=new JArray(),["weakening"]=new JArray(),["penetration"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()}};
  internal static JObject Action(JObject p,JObject pipeline)=>new JObject{["sourceId"]=p["original"]["damage"]["sourceId"].DeepClone(),["kind"]="RAW_ACTION_DAMAGE",["pipeline"]=pipeline,["riskAppliedVersion"]=null,["progressAppliedVersion"]=null};
  [Test] public void TrustedVLateKeepsRawActionSeparateAndResolvesOriginalDefenseOnce(){var p=Packet();var source=Read(p);var hp=(JObject)source.GetType().GetProperty("ScaledHp").GetValue(source);Assert.AreEqual("1610",(string)hp["exact"]["numerator"]);var damage=(JObject)source.GetType().GetProperty("ScaledDamage").GetValue(source);Assert.AreEqual("126",(string)damage["exact"]["numerator"]);var result=(CombatNumericDefenseResult)Invoke(source,"ResolveOriginalAction",Action(p,Pipeline()));Assert.AreEqual(63,result.ToVitalsMagnitude());}
  [Test] public void OtherRunCannotRestoreDespiteCorrectPacketHash(){var p=Packet();var b=(JObject)p["binding"].DeepClone();b["runId"]="other-run";Assert.Throws<ArgumentException>(()=>Read(p,b,(string)p["packetHash"]));}
  [Test] public void DoubleAppliedActionMarkerAndActorAtkSubstitutionAreRejected(){var p=Packet();var source=Read(p);var marked=Action(p,Pipeline());marked["riskAppliedVersion"]="combat.b-operation-risk.v1.20261003";Assert.Throws<ArgumentException>(()=>Invoke(source,"ResolveOriginalAction",marked));var atk=Action(p,Pipeline(new JObject{["numerator"]="126",["denominator"]="1"}));Assert.Throws<ArgumentException>(()=>Invoke(source,"ResolveOriginalAction",atk));}
  internal static BCombatFormation Formation()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("car0","op_mira")});
  internal static BCombatHpBinding[] HpBindings()=>new[]{new BCombatHpBinding("train",5000),new BCombatHpBinding("car0",1000),new BCombatHpBinding("op_mira",1520)};
  static object Local(object source,int capacity=10000){var type=typeof(CombatExactValue).Assembly.GetType("LastRail.Battle.BOperationRiskLocalConsumer");Assert.NotNull(type,"Missing risk composition into original native HP owner");return Invoke(type,"CreateLocalValidation",source,Formation(),HpBindings(),capacity);}
  [Test] public void LocalExactDefenseThenOriginalShieldHpAndThirtyPercentRouterApplyOnce(){var p=Packet();var owner=Local(Read(p));Invoke(owner,"ApplyOriginalShield","shield","car0",new CombatShieldSource("LOCAL_ORIGINAL","risk-trial-shield",0),50,100L,0L);var receipt=Invoke(owner,"ApplyOriginalAction","hit","car0",1L,Action(p,Pipeline()),false);Assert.AreEqual(987,Invoke(owner,"Hp","car0"));Assert.AreEqual(4997,Invoke(owner,"Hp","train"));var before=(JObject)Invoke(owner,"Capture");Assert.AreSame(receipt,Invoke(owner,"ApplyOriginalAction","hit","car0",1L,Action(p,Pipeline()),false));Assert.IsTrue(JToken.DeepEquals(before,(JObject)Invoke(owner,"Capture")));var type=owner.GetType();var restored=Invoke(type,"RestoreLocalValidation",before,Read(p),Formation(),HpBindings(),10000);Assert.IsTrue(JToken.DeepEquals(before,(JObject)Invoke(restored,"Capture")));}
  [Test] public void NativeOverflowAndCapacityCannotPublishRiskOrHpPartialState(){var p=Packet();var owner=Local(Read(p),1);Invoke(owner,"ApplyOriginalAction","hit","car0",1L,Action(p,Pipeline()),false);var before=(JObject)Invoke(owner,"Capture");Assert.Throws<ArgumentException>(()=>Invoke(owner,"ApplyOriginalAction","capacity","car0",2L,Action(p,Pipeline()),false));Assert.IsTrue(JToken.DeepEquals(before,(JObject)Invoke(owner,"Capture")));}
  [Test] public void RiskTransportProvidesStandaloneOwnedSignedExchange(){Assert.NotNull(typeof(CombatExactValue).Assembly.GetType("LastRail.Battle.BOperationRiskHttpTransport"),"Missing standalone authenticated source boundary");}
  internal static JObject Rebind(string risk,string progress,string numerator="60",string denominator="1",string kind="BASE_HP"){
   var p=Packet();p["binding"]["risk"]=risk;p["binding"]["progress"]=progress;p["original"]["hp"]["kind"]=kind;p["original"]["damage"]["value"]=new JObject{["numerator"]=numerator,["denominator"]=denominator};p["binding"]["rawSourceHash"]=BDirectAttackInput.Digest(p["original"]);
   var definition=(JObject)p["definition"];var r=((JArray)definition["risks"]).Single(x=>(string)x["id"]==risk);var band=((JArray)definition["progress"]).Single(x=>(string)x["id"]==progress);p["scaled"]["hp"]["kind"]=kind;p["scaled"]["hp"]["exact"]=CombatExactValue.From((JObject)p["original"]["hp"]["value"]).Multiply(CombatExactValue.From((JObject)r["hp"])).Snapshot();p["scaled"]["damage"]["exact"]=CombatExactValue.From((JObject)p["original"]["damage"]["value"]).Multiply(CombatExactValue.From((JObject)r["damage"])).Multiply(CombatExactValue.From((JObject)band["damage"])).Snapshot();return Rehash(p);
  }
  internal static JObject Rehash(JObject p){p.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(p);return p;}
  [Test] public void AllFifteenApprovedFactorsKeepHpIndependentOfProgress(){string[] risks={"I","II","III","IV","V"},bands={"EARLY","MIDDLE","LATE"};int[] hp={700,875,1085,1330,1610};int[,] damage={{60,66,72},{69,75,82},{78,85,93},{90,99,108},{105,115,126}};for(int i=0;i<5;i++)for(int j=0;j<3;j++){var p=Rebind(risks[i],bands[j]);var source=(BOperationRiskSource)Read(p);Assert.AreEqual(hp[i],source.BaseHpAllocationMagnitude());Assert.AreEqual(damage[i,j],source.ResolveOriginalAction(Action(p,Pipeline(defense:0))).ToVitalsMagnitude());Assert.IsFalse(source.MissionSupported);Assert.IsFalse(source.HpSpawnConversionSupported);}}
  [Test] public void FractionsRemainExactUntilOriginalPipelineFinalFloor(){var p=Rebind("V","LATE","1","3");var source=(BOperationRiskSource)Read(p);Assert.AreEqual("7",(string)source.ScaledDamage["exact"]["numerator"]);Assert.AreEqual("10",(string)source.ScaledDamage["exact"]["denominator"]);var pipeline=Pipeline((JObject)p["original"]["damage"]["value"],0);pipeline["effects"]=new JArray(new JObject{["sourceId"]="local-equip",["group"]="EQUIPMENT_DIRECT",["valueBps"]=10000});Assert.AreEqual(1,source.ResolveOriginalAction(Action(p,pipeline)).ToVitalsMagnitude());}
  [Test] public void EhpBudgetCannotAlsoBecomeSpawnHp(){var p=Rebind("V","LATE",kind:"EHP_BUDGET");var source=(BOperationRiskSource)Read(p);Assert.AreEqual("1610",(string)source.ScaledHp["exact"]["numerator"]);Assert.Throws<ArgumentException>(()=>source.BaseHpAllocationMagnitude());}
  [Test] public void RehashedDefinitionAppliedFlagsAndScaledTamperingFail(){var p=Packet();p["definition"]["risks"][0]["hp"]["numerator"]="2";Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));p=Packet();p["original"]["hp"]["riskAppliedVersion"]=BOperationRiskSource.Version;Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));p=Packet();p["scaled"]["damage"]["exact"]["numerator"]="252";Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}
  [Test] public void OverflowChangedReplayAndCorruptRestoreNeverPublish(){var p=Rebind("V","LATE","999999999999999999999999999999");var source=(BOperationRiskSource)Read(p);var owner=BOperationRiskLocalConsumer.CreateLocalValidation(source,Formation(),HpBindings(),10);var before=owner.Capture();Assert.Throws<OverflowException>(()=>owner.ApplyOriginalAction("overflow","car0",1,Action(p,Pipeline((JObject)p["original"]["damage"]["value"]))));Assert.IsTrue(JToken.DeepEquals(before,owner.Capture()));p=Packet();source=(BOperationRiskSource)Read(p);owner=BOperationRiskLocalConsumer.CreateLocalValidation(source,Formation(),HpBindings(),10);owner.ApplyOriginalAction("hit","car0",1,Action(p,Pipeline()));before=owner.Capture();Assert.Throws<ArgumentException>(()=>owner.ApplyOriginalAction("hit","train",1,Action(p,Pipeline())));Assert.IsTrue(JToken.DeepEquals(before,owner.Capture()));var corrupt=(JObject)before.DeepClone();corrupt["native"]["lastTick"]=2;Assert.Throws<ArgumentException>(()=>BOperationRiskLocalConsumer.RestoreLocalValidation(corrupt,source,Formation(),HpBindings(),10));}
 }
}
#endif
